import { createCipheriv, createDecipheriv } from 'node:crypto'
import { aesInitCheck, aesParamsCheck, aesMethods } from './utils/aes.mjs'
import { assert } from './utils/assertUint8.mjs'
import { createCipherApi } from './utils/cipher.mjs'

// Node.js based implementation (significantly faster than Node.js WebCrypto-based one)

function aesNodeType(mode, len) {
  assert(len === 16 || len === 24 || len === 32, 'Invalid key size')
  const bits = len * 8
  if (mode === 'CBC') return `aes-${bits}-cbc`
  if (mode === 'CTR') return `aes-${bits}-ctr`
  if (mode === 'GCM') return `aes-${bits}-gcm`
  throw new Error('Unexpected AES mode')
}

export async function aes(mode, key, usage) {
  aesInitCheck(mode, key, usage)
  const algorithm = aesNodeType(mode, key.length)

  return createCipherApi(usage, {
    async encrypt(data, nonce, additionalData) {
      aesParamsCheck(mode, nonce, additionalData)
      const cipher = createCipheriv(algorithm, key, nonce, { authTagLength: 16 })
      if (additionalData) cipher.setAAD(additionalData)
      const parts = [cipher.update(data), cipher.final()]
      if (mode === 'GCM') parts.push(cipher.getAuthTag())
      return Buffer.concat(parts)
    },
    async decrypt(data, nonce, additionalData) {
      aesParamsCheck(mode, nonce, additionalData)
      const decipher = createDecipheriv(algorithm, key, nonce, { authTagLength: 16 })
      if (additionalData) decipher.setAAD(additionalData)
      let encrypted = data
      if (mode === 'GCM') {
        assert(data.length >= 16, 'In GCM mode, encrypted data should be at least 16 bytes long') // tag suffix
        decipher.setAuthTag(data.subarray(-16))
        encrypted = data.subarray(0, -16)
      }
      return Buffer.concat([decipher.update(encrypted), decipher.final()])
    },
  })
}

const { encryptCBC, decryptCBC, encryptCTR, decryptCTR, encryptGCM, decryptGCM } = aesMethods(aes)

export { encryptCBC, decryptCBC, encryptCTR, decryptCTR, encryptGCM, decryptGCM }
